#!/usr/bin/env python3
import base64
import socket
import socketserver
import sys
import threading

UPSTREAM = ("172.22.13.146", 3128)
USERPASS = "svc_proxy_nonrte_netgrp:jLNgeTuuCdbu9h9kesPaA4iEDrzHvXtR"
AUTH = "Proxy-Authorization: Basic " + base64.b64encode(USERPASS.encode()).decode()


def pump(src, dst):
    try:
        while True:
            data = src.recv(65536)
            if not data:
                break
            dst.sendall(data)
    except OSError:
        pass
    finally:
        try:
            dst.shutdown(socket.SHUT_WR)
        except OSError:
            pass


class Handler(socketserver.BaseRequestHandler):
    def handle(self):
        client = self.request
        try:
            header = b""
            while b"\r\n\r\n" not in header:
                chunk = client.recv(4096)
                if not chunk:
                    return
                header += chunk
                if len(header) > 65536:
                    return
            head, rest = header.split(b"\r\n\r\n", 1)
            lines = head.split(b"\r\n")
            lines = [l for l in lines if not l.lower().startswith(b"proxy-authorization:")]
            first = lines[0]
            if first.startswith((b"CONNECT ", b"GET ", b"HEAD ", b"POST ", b"PUT ")):
                lines.insert(1, AUTH.encode())
            out_header = b"\r\n".join(lines) + b"\r\n\r\n"
            upstream = socket.create_connection(UPSTREAM, timeout=30)
            upstream.sendall(out_header + rest)
            threading.Thread(target=pump, args=(client, upstream), daemon=True).start()
            pump(upstream, client)
        except OSError as e:
            sys.stderr.write("proxypass error: %s\n" % e)
        finally:
            try:
                client.close()
            except OSError:
                pass


class ThreadedServer(socketserver.ThreadingTCPServer):
    allow_reuse_address = True
    daemon_threads = True


if __name__ == "__main__":
    port = int(sys.argv[1]) if len(sys.argv) > 1 else 3129
    with ThreadedServer(("127.0.0.1", port), Handler) as srv:
        print("proxypass listening on", port, flush=True)
        srv.serve_forever()

