  static final ClassName GENERATE_RULES_ANNOTATION =
      ClassName.get("dagger.android.internal", "GenerateAndroidInjectionProguardRules");

  private final XProcessingEnv env;

  ProguardProcessingStep(XProcessingEnv env) {
