#!/usr/bin/env python3
import base64
import socket
import threading

LISTEN = ("127.0.0.1", 8899)
UPSTREAM_HOST = "172.22.13.146"
UPSTREAM_PORT = 3128
USER = "svc_proxy_nonrte_netgrp"
PASS = "jLNgeTuuCdbu9h9kesPaA4iEDrzHvXtR"

AUTH = base64.b64encode(("%s:%s" % (USER, PASS)).encode()).decode()

UPSTREAM = (UPSTREAM_HOST, UPSTREAM_PORT)


def recv_headers(conn):
    data = b""
    while b"\r\n\r\n" not in data:
        chunk = conn.recv(4096)
        if not chunk:
            break
        data += chunk
    return data


def relay(a, b):
    try:
        while True:
            data = a.recv(65536)
            if not data:
                break
            b.sendall(data)
    except OSError:
        pass
    finally:
        for s in (a, b):
            try:
                s.shutdown(socket.SHUT_RDWR)
            except OSError:
                pass
            try:
                s.close()
            except OSError:
                pass


def handle(client):
    try:
        req = recv_headers(client)
        if not req:
            client.close()
            return
        first_line = req.split(b"\r\n", 1)[0].decode("latin1", "replace")
        parts = first_line.split(" ")
        method = parts[0].upper()
        target = parts[1]

        if method == "CONNECT":
            hostport = target
            upstream = socket.create_connection(UPSTREAM, timeout=60)
            connect_req = (
                "CONNECT %s HTTP/1.1\r\nHost: %s\r\n"
                "Proxy-Authorization: Basic %s\r\n\r\n" % (hostport, hostport, AUTH)
            ).encode()
            upstream.sendall(connect_req)
            resp = recv_headers(upstream)
            if b" 200 " not in resp.split(b"\r\n", 1)[0]:
                print("UPSTREAM CONNECT failed: %r" % resp)
                upstream.close()
                client.close()
                return
            client.sendall(b"HTTP/1.1 200 Connection established\r\n\r\n")
            relay(client, upstream)
        else:
            upstream = socket.create_connection(UPSTREAM, timeout=60)
            # Inject Proxy-Authorization after the first line.
            headers = req.split(b"\r\n")
            lines = [headers[0]]
            for h in headers[1:]:
                if b"\r\n\r\n" in h:
                    lines.append(h)
                    lines.append(b"Proxy-Authorization: Basic %s" % AUTH.encode())
                else:
                    lines.append(h)
            out = b"\r\n".join(lines)
            upstream.sendall(out)
            relay(upstream, client)
    except Exception as e:  # noqa: BLE001
        print("proxy error: %r" % e)
        try:
            client.close()
        except OSError:
            pass


def main():
    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    s.bind(LISTEN)
    s.listen(128)
    print("listening on %s:%s" % LISTEN)
    while True:
        c, _ = s.accept()
        threading.Thread(target=handle, args=(c,), daemon=True).start()


if __name__ == "__main__":
    main()

